        a = int(assign['a_coef'])
        r = int(assign['c_scale'])
    except Exception:
        # missing or invalid types
        return (False, None)

    if m < 2 or a <= 0 or r <= 0:
        # enforce nontrivial instance
        return (False, None)

    # Closed-form answer
    val_x = (2.0**m) * (m**(m-1)) * (a**(m - 0.5)) / ((2*m - 1)**(m - 0.5))
    val_c = 13.0 / 7.0
    answer = val_x * val_c

    # Light randomized sanity check enforcing non-triviality and correctness
    # Define the objective function
    def obj(xs, c):
        # xs: list of length m with nonnegative entries
        # c: real
        rc = r * c
        denom_c = 7.0*math.sqrt(3.0)*rc + 14.0*math.sqrt(1.0 + rc*rc)
        num_c = 49.0 + 6.0*rc*rc + 4.0*rc*math.sqrt(3.0 + 3.0*rc*rc)
        sum_x = sum(xs)
        if sum_x <= 0:
            return float('inf')
        prod_x = 1.0
        for x in xs:
            if x < 0:
                return float('inf')
            prod_x *= (a + x*x)
        return (prod_x * num_c) / (denom_c * sum_x)

    # theoretical minimizers
    s_opt = m * math.sqrt(a / (2.0*m - 1.0))
    c_opt = math.sqrt(3.0) / r
    x_equal = [s_opt / m] * m
    best = obj(x_equal, c_opt)

    # Ensure the computed best matches the closed form within tolerance
    if not (abs(best - answer) <= 1e-9 * max(1.0, answer)):
        return (False, None)

    # Random samples around the neighborhood and broader region
    rng_state = 1234567  # deterministic simple LCG for reproducibility
    def urand():
        nonlocal rng_state
        rng_state = (1103515245 * rng_state + 12345) & 0x7fffffff
        return (rng_state / 0x7fffffff)

    min_sample = float('inf')
    # include exact equal case
    min_sample = min(min_sample, best)

    # sample different sums and distributions of x, and various c
    for _ in range(800):
        # choose total sum S in a reasonable range around s_opt
        S = s_opt * (0.2 + 2.8 * urand())
        # generate random positive weights
        ws = [urand() + 1e-6 for __ in range(m)]
        sw = sum(ws)
        xs = [S * w / sw for w in ws]
        # pick c in a range around c_opt
        c = (2.0 * urand() - 0.2) * c_opt  # allow slight negative too
        val = obj(xs, c)
        if val < min_sample:
            min_sample = val

    # numerical sanity: samples should not beat the theoretical minimum beyond a tiny epsilon
    if min_sample + 1e-8 < answer:
        # Found a sample that appears to contradict the bound; reject instance
        return (False, None)

    return (True, answer)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
